  isOnMap(cell) {
    return cell.x >= 0 && cell.x < this._width && cell.y >= 0 && cell.y < this._height;
  }
  neighborsWithDiag(tile) {
    const x = this.x(tile);
    const y = this.y(tile);
    const ns = [];
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue; // Skip the center tile
        const newX = x + dx;
        const newY = y + dy;
        if (newX >= 0 && newX < this._width && newY >= 0 && newY < this._height) {
          ns.push(this._map.ref(newX, newY));
        }
      }
    }
    return ns;
  }

